import React from "react";

const money=v=>new Intl.NumberFormat("fr-GA").format(v)+" FCFA";
// Only accept same-origin endpoints generated by the private commercial API.
const validUrl=url=>typeof url==="string"&&/^\/api\/v1\/(?:platform\/schools\/[0-9a-f-]+\/subscriptions|schools\/[0-9a-f-]+\/owner\/subscriptions)\/\d+\/(?:invoice|payments\/\d+\/receipt|amendments\/\d+\/document)$/.test(url);
function DocumentLinks({doc,label}){
  if(!validUrl(doc?.url))return null;
  return <span>
    <a className="ya-btn ya-btn-outline" href={doc.url+"?preview=1"} target="_blank" rel="noopener noreferrer">Ouvrir {label}</a>{" "}
    <a className="ya-btn ya-btn-outline" href={doc.url}>Télécharger {label} (PDF)</a>
  </span>;
}
export default function SubscriptionDocuments({documents}){
  if(!documents?.invoice)return null;
  return <section aria-label="Documents commerciaux privés">
    <h3>Factures et reçus commerciaux</h3>
    <p className="hint">Documents BWETEK Informatyk — distincts de la caisse scolaire. Facture commerciale, mentions fiscales à compléter.</p>
    <p>{documents.invoice.reference} — <DocumentLinks doc={documents.invoice} label="la facture"/></p>
    {(documents.amendments||[]).map(a=><div key={a.id} className="ya-info-row"><span>{a.reference} · {money(a.amount_xaf)}</span><DocumentLinks doc={a} label="l’avenant"/></div>)}
    {(documents.receipts||[]).map(r=><div key={r.id} className="ya-info-row">
      <span>{r.reference} · {money(r.amount_xaf)}{r.voided?" · ANNULÉ":""}</span>
      <DocumentLinks doc={r} label={r.voided?"le reçu annulé":"le reçu"}/>
    </div>)}
    {!documents.receipts?.length&&<p>Aucun reçu de règlement émis.</p>}
  </section>;
}
